<?php
namespace App\Http\Controllers;
use App\Http\Requests\CategoryRequest; use App\Models\Category; use Illuminate\Http\Request;
class CategoryController extends Controller { public function index(Request $r){return response()->json(['data'=>Category::where('restaurant_id',$r->user()->restaurant_id)->orderBy('display_order')->get()]);} public function store(CategoryRequest $r){$c=Category::create(['restaurant_id'=>$r->user()->restaurant_id,...$r->validated()]);return response()->json(['data'=>$c],201);} public function show(Request $r,int $id){return response()->json(['data'=>Category::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id)]);} public function update(CategoryRequest $r,int $id){$c=Category::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id);$c->update($r->validated());return response()->json(['data'=>$c]);} public function destroy(Request $r,int $id){Category::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id)->delete();return response()->json(['message'=>'تم حذف الفئة بنجاح']);} }
